struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/*
 * A BURST SLOT — the envelope, and the whole of what changed in pass 3.
 *
 * Each slot is an independent, deterministic pulse train on ONE cell: a period in frames,
 * a lifetime of a few frames, and a per-cycle roll that decides whether this cycle fires
 * at all. A cell's phase inside its own slot is hashed from its index, so thirty-six cells
 * on the same slot are thirty-six unsynchronised trains rather than one flashbulb.
 *
 * Returns the burst's AGE in frames, or -1 when the slot is quiet.
 *
 * The periods are co-prime frame counts, so two slots on one cell realign only every
 * few hundred frames and three of them effectively never. That is what "multiple random
 * glitches" needs and a single tick cannot give: several short events in flight at
 * different phases.
 */
fn slot(index: u32, seed: u32, salt: u32, period: f32, life: f32, chance: f32, frame: f32) -> f32 {
  /* Per-cell phase, so the wall does not pulse in unison. */
  let shifted = frame + (hashU((index * 7919u) ^ salt) * period);
  let cycle = floor(shifted / period);
  let age = shifted - (cycle * period);
  if (age >= life) { return -1.0; }
  if (hashU((index * 1013u) + (seed * 6151u) + salt + (u32(cycle) * 3571u)) >= chance) { return -1.0; }
  return age;
}

/* Co-prime frame periods. Nothing here shares a factor with anything else here. */
const TEAR_A: f32 = 17.0;
const TEAR_B: f32 = 23.0;
const TEAR_C: f32 = 31.0;
const SNOW_A: f32 = 13.0;
const SNOW_B: f32 = 19.0;
const DROP_P: f32 = 47.0;

/*
 * LIFETIMES, in frames, and they are the owner's note made numeric. A tear that lasts two
 * or three frames at 60 fps is 33-50 ms — a flicker you catch rather than a state you
 * watch. Snow is shorter still. A DROPOUT is the exception and holds for a fifth of a
 * second, because it is not damage: it is the cell briefly becoming a different picture,
 * and a two-frame version of that reads as a dropped frame rather than as an idea.
 */
const TEAR_LIFE: f32 = 3.0;
/*
 * FOUR, and the previous value was the owner's whole complaint: "the static noise in the
 * glitch animation is like just ONE FRAME — that looks not well blended". It literally
 * was. The second snow train ran at SNOW_LIFE - 1, so at SNOW_LIFE = 2 it was a
 * single-frame flash — and a single frame does not read as texture, it reads as a POP.
 * The tears were given 2-3 frames for exactly this reason and the static never got the
 * same treatment. At 4 and 3 it lasts long enough to be seen as grain.
 *
 * SNOW_SHARE comes down with it (0.35 -> 0.18) so the DUTY CYCLE barely moves: life/period
 * x chance was (2/13 + 1/19) x 0.35 = 0.073 and is now (4/13 + 3/19) x 0.18 = 0.084. A
 * longer event that fires proportionally less often is the whole trade; leaving the share
 * alone would have doubled the amount of static on the wall.
 */
const SNOW_LIFE: f32 = 4.0;
const DROP_LIFE: f32 = 12.0;

/* Relative rarity. A tear is the wall's ordinary weather; snow is an interruption; a
   dropout is an EVENT, because it changes what the cell is a picture OF. */
/*
 * How deep the grain modulates what is already there. Bounded above by construction (see
 * the SNOW branch), so this is a texture depth and not a clipping risk.
 *
 * 0.30, down from 0.45, on the owner's "too bright" a second time — and it is the
 * SECOND half of that repair, not the whole of it: the brightening was the silhouette
 * term (see the SNOW branch), and dropping the depth without deleting that would have
 * been another dimmer wrong picture.
 *
 * It stays modest for the RECOLORIZER's sake too: a Lookup turns luminance into a palette
 * position, so a deep luminance grain walks the whole palette between neighbouring texels
 * and monochrome noise arrives as multicoloured confetti (§V853). Measured after this
 * change, chroma across a snowing cell moves less than the clean cell's, so the grain is
 * staying inside one region of the palette.
 */
const SNOW_DEPTH: f32 = 0.3;

const TEAR_SHARE: f32 = 0.55;
const SNOW_SHARE: f32 = 0.18;
const DROP_SHARE: f32 = 0.30;

fn luma(rgb: vec3f) -> f32 {
  return dot(rgb, vec3f(0.2126, 0.7152, 0.0722));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return vec4f(here.rgb, 1.0); }

  let cell = gridCellAt(uv, params.grid);
  let index = u32(cell.index);
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  /* FRAMES, not seconds: an event two frames long has to be counted in the unit it is two
     of. absFrame is the deterministic frame count the transport supplies (§V44) — never a
     wall clock. Rate stretches or compresses every period together, so the whole wall
     speeds up as one instrument. max(0.25) keeps the trains turning at Rate 0. */
  let frame = frameU.absFrame * max(0.25, params.rate);
  let tick = u32(frame);

  /* THE AUDIO GATE: this cell's own centre texel. Bright cells are dealt in first, so a
     source that responds to the music makes the damage chase the beat across the wall. */
  let middle = vec2i(clamp((cell.origin + (0.5 * cell.size)) * dims, vec2f(0.0), dims - vec2f(1.0)));
  let lit = clamp(luma(textureLoad(inputTexture, middle, 0).rgb), 0.0, 1.0);
  let base = clamp(params.amount * (0.2 + (1.8 * lit)), 0.0, 1.0);

  /* THREE TEAR TRAINS, TWO SNOW TRAINS, ONE DROPOUT — all independent, all per cell. */
  let tearAge = max(
    slot(index, seed, 101u, TEAR_A, TEAR_LIFE, base * TEAR_SHARE, frame),
    max(
      slot(index, seed, 211u, TEAR_B, TEAR_LIFE - 1.0, base * TEAR_SHARE, frame),
      slot(index, seed, 307u, TEAR_C, TEAR_LIFE, base * TEAR_SHARE, frame)));
  let snowAge = max(
    slot(index, seed, 409u, SNOW_A, SNOW_LIFE, base * SNOW_SHARE, frame),
    slot(index, seed, 521u, SNOW_B, SNOW_LIFE - 1.0, base * SNOW_SHARE, frame));
  let dropAge = slot(index, seed, 631u, DROP_P, DROP_LIFE, base * DROP_SHARE, frame);

  /* EXCLUSIVE, rarest first. One thing per cell per frame, on purpose: at 6x6 a cell is a
     couple of thousand pixels and a tear under snow is mud. The variety is in WHICH cells
     and WHICH kind, and it is asserted. */
  if (dropAge >= 0.0) {
    /* DROPOUT — the background falls away. Alpha arrived here as the MATTE, packed into
       the picture before the ring (see the component's pack node), so it has been delayed
       by exactly the same number of frames as the colour it belongs to: a cell holding a
       moment from a second ago drops the background of THAT moment, not of now. */
    return vec4f(here.rgb * clamp(here.a, 0.0, 1.0), 1.0);
  }

  if (snowAge >= 0.0) {
    /*
     * SNOW — and this branch has been rebuilt twice, both times at the cause.
     *
     * WHAT IT LOOKED LIKE WHEN IT WAS WRONG: the owner photographed a two-cell block of
     * full-intensity multicoloured confetti with none of the picture left in it. Three
     * separate faults, none of them a level:
     *
     *  1. IT REPLACED THE PICTURE. mix(silhouette, grain, 0.65) writes a value that owes
     *     almost nothing to what was there, so a cell stopped being a picture. Static has
     *     to RIDE the image — that is the difference between static and a dropout, and
     *     this component already has a dropout.
     *  2. IT CAME OUT CHROMATIC, and not because the grain was. The grain is monochrome
     *     here and always was; the CONFETTI is made downstream, by the recolorizer. A
     *     Lookup maps luminance to a palette position, so a full-swing luminance grain
     *     walks the whole palette between adjacent texels and monochrome noise arrives on
     *     screen as per-pixel colour garbage. The fix is at this end: keep the luminance
     *     excursion small enough that the palette index barely moves, and the same noise
     *     reads as grain instead.
     *  3. IT WAS TOO BIG AND TOO SOLID. A whole cell of it is a rectangle, and a rectangle
     *     is a graphic, not a fault. It is banded now — a few scanline bands per burst —
     *     so it reads as a monitor breaking up rather than as a filled shape.
     *
     * MULTIPLICATIVE, AND HIGHLIGHT-PROTECTED (§V833/§V838). The output is bounded by
     * crushed * (1 + SNOW_DEPTH), and the weight is already ~0 wherever the pixel is
     * bright — so it cannot reach the clip BY CONSTRUCTION, not by tuning. The owner's
     * "it oversteers, overflows" was literal: it was clipping to flat white, and a lower
     * amount would only have made a dimmer wrong picture. The gate asserts the property
     * rather than the number: zero pixels at 1.0 anywhere in a snowing wall.
     *
     */
    let grain = hashU((u32(texel.x) * 73856093u) ^ (u32(texel.y) * 19349663u) ^ (tick * 83492791u) ^ seed);
    /* SCANLINE BANDS, not the whole cell: only some of them break up on a given burst. */
    let bandCount = 5.0 + floor(hashU((index * 5501u) + (tick * 79u) + seed) * 7.0);
    let bandIndex = u32(floor(cell.local.y * bandCount));
    let banded = select(0.35, 1.0, hashU((bandIndex * 2237u) + (index * 91u) + (tick * 397u) + seed) < 0.45);
    /*
     * GRAIN ON THE PICTURE. Two things were removed here, and BOTH were measured before
     * being touched, because "too bright" had already survived one repair.
     *
     * 1. THE SILHOUETTE LIFT. mix(base, step(0.35, base), 0.25) raised every pixel above
     *    the threshold by 0.25 x (1 - base) — a flat +0.10 on a bright cell before any
     *    grain existed. Measured: a snowing cell's mean read 0.7315 against the clean
     *    cell's 0.6853. It was never snow's job; Crush is a published knob with a level
     *    node behind it, and a second hidden discontinuous threshold inside one
     *    degradation is how a control surface stops being trustworthy. Deleted, not
     *    reduced.
     *
     * 2. THE DESATURATION. Writing luma into all three channels made the cell a GREY
     *    PATCH — the owner's "out of place" — and it also made it read brighter for a
     *    reason no amount of level-tweaking would have fixed: the sink's transfer is
     *    concave, so luma-of-encoded is not encode-of-luma, and a monochrome cell at
     *    IDENTICAL linear luminance measures 0.7042 encoded against a colour cell's
     *    0.6853. The picture was not brighter; it had stopped being the picture. So the
     *    grain now rides the colour instead of replacing it, which is what film grain is.
     *
     * §V853 was the third suspect and the same measurement CLEARED it: chroma after the
     * palette went 0.546 -> 0.540, DOWN. The lookup was not amplifying grain into a
     * dimension it lacked.
     *
     * What is left is a symmetric multiplicative modulation, so its expected shift in
     * LINEAR luminance is zero by construction — measured at 0.4841 -> 0.4842, and that is
     * what the gate asserts. Every pixel of a snowing cell is therefore a positive SCALING
     * of the pixel that was there, which is also how the gate tells snow from a tear (a
     * tear moves pixels) and from a dropout (which zeroes them).
     */
    /*
     * The weight is keyed on the PEAK CHANNEL, not on luminance, and that is a correctness
     * fix rather than a nicety: clipping happens per channel, so protection has to be
     * measured per channel. Keyed on luma, a pixel at luma 0.5 could still carry a red of
     * 0.95, get the full grain because its luma looked safe, and clamp — measured, that
     * pushed 7005 pixels onto the sink's ceiling against a clean frame's 3456. Keyed on
     * the peak, the product peak x (1 + SNOW_DEPTH x weight(peak)) tops out around 0.9
     * across the whole range, so nothing can reach the clamp at all.
     */
    let peak = max(here.r, max(here.g, here.b));
    let weight = (1.0 - smoothstep(0.30, 0.92, peak)) * banded;
    let value = here.rgb * (1.0 + (SNOW_DEPTH * weight * ((grain * 2.0) - 1.0)));
    return vec4f(value, 1.0);
  }

  if (tearAge >= 0.0) {
    /*
     * TEAR — bands shove sideways with an RGB fringe riding the same displacement.
     *
     * PASS 3 CHANGED THE ENVELOPE, not the mechanism. Every one of these numbers now
     * re-deals on the FRAME rather than being held for a whole tick: a burst is two or
     * three frames long and the bands jump within it, which is what a glitch looks like.
     * Held for a tick — the pass-2 design — it was one clean state sitting there for half
     * a second, and the owner's verdict was that it read as slow and simplified.
     */
    let strength = params.amount * (0.35 + (0.65 * hashU((index * 337u) + (tick * 61u) + seed)));
    let bands = 4.0 + floor(hashU((index * 977u) + (tick * 131u) + seed) * 12.0);
    let band = u32(floor(cell.local.y * bands));
    let shove = (hashU((band * 1471u) + (index * 29u) + (tick * 523u) + seed) - 0.5) * 0.7 * strength;
    let split = 0.06 * strength;
    let mid = tap(cell, shove);
    let red = tap(cell, shove + split);
    let blue = tap(cell, shove - split);
    return vec4f(red.r, mid.g, blue.b, 1.0);
  }

  return vec4f(here.rgb, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  mode: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

const SHOT_ANGLES: f32 = 4.0;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let cell = gridCellAt(uv, params.grid);
  let index = cell.index;
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  let mode = i32(params.mode + 0.5);

  var delay = 0.0;
  if (mode == 1) {
    /* ORDERED — the cascade. Reading order, oldest at the bottom right. */
    delay = index / cell.last;
  } else if (mode == 2) {
    /* RANDOM — every cell its own moment, held. Seeded, so it is a LOOK, not noise. */
    delay = hashU((u32(index) * 1973u) + (seed * 9277u));
  } else if (mode == 3) {
    /*
     * SWEEP — the owner's "freeze that wanders through".
     *
     * Each cell's delay RAMPS, so it looks one frame further back every frame: at
     * Rate 1.0 (with Spread 1) that is exactly one ring-frame per rendered frame, and
     * the cell holds STILL while the world moves on. The phase offset per cell means
     * they wrap at different times, so the wall refreshes as a rolling wave rather than
     * all at once. Below 1.0 the held frame plays in slow motion; above it, backwards.
     */
    delay = fract((index / cell.count) + (frameU.absTime * params.rate));
  } else if (mode == 4) {
    /*
     * SHOTS — several angles of one scene, cut on a clock.
     *
     * Cells are dealt to SHOT_ANGLES groups by the seeded hash and every group holds one
     * rung of the delay ladder; the ladder rotates one rung per tick, so the whole wall
     * re-cuts at once and then holds. Distinct from RANDOM, which never re-cuts, and from
     * SWEEP, which never holds a whole group together.
     */
    let angle = floor(hashU((u32(index) * 6151u) + (seed * 1543u)) * SHOT_ANGLES);
    let turn = floor(frameU.absTime * max(0.0, params.rate));
    delay = ((angle + turn) % SHOT_ANGLES) / (SHOT_ANGLES - 1.0);
  }
  /* mode 0 — UNIFORM — falls through at 0.0: every cell reads the newest recorded frame,
     so the wall is the plain tiling and the scan is a no-op you can see (§V147's shape). */

  return vec4f(delay, delay, delay, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/* Slow against everything else on the wall: one pass every ~7.7 s at Rate 1. The whole
   point of a sweep is that you wait for it. */
const SWEEP_HZ: f32 = 0.13;
/* Half-width, in frame widths. 0.22 puts the band across about two cells of a 6-wide wall
   — wide enough to read as a front travelling, narrow enough to leave somewhere clean. */
const SWEEP_HALF_WIDTH: f32 = 0.22;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return here; }

  let centre = fract(frameU.absTime * SWEEP_HZ * max(0.05, params.rate));
  let distance = abs(uv.x - centre);
  /* Wrapped, so the band leaves the right edge and arrives at the left. */
  let wrapped = min(distance, 1.0 - distance);
  let band = 1.0 - smoothstep(0.0, SWEEP_HALF_WIDTH, wrapped);
  if (band <= 0.0) { return here; }

  let cell = gridCellAt(uv, params.grid);
  /* 0.12 of a CELL width at full Chroma, measured against the picture rather than
     chosen: at 0.05 the fringe was under two texels on a 6-wide wall and did not read. */
  let shift = 0.12 * params.amount * band;
  let red = tap(cell, shift);
  let blue = tap(cell, -shift);
  return vec4f(red.r, here.g, blue.b, here.a);
}

struct Params {
  strength: f32, // @default 0.35 Scattered highlight energy.
  threshold: f32, // @default 0.8 Highlight extraction threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> params: Params;
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
  let base=textureSampleLevel(inputTexture,inputSampler,uv,0.0).rgb;
  let brightness=max(base.r,max(base.g,base.b));
  let knee=max(params.threshold*0.5,0.0001);
  let soft=clamp(brightness-params.threshold+knee,0.0,2.0*knee);
  let contribution=max(brightness-params.threshold,soft*soft/(4.0*knee))/max(brightness,0.0001);
  return vec4f(base*contribution*params.strength,1);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler:sampler;
@group(0) @binding(1) var inputTexture:texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU:SharedFrame;
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
  let dims=vec2f(textureDimensions(inputTexture));
  let sourceAspect=dims.x/dims.y;
  let outputAspect=16.0/9.0;
  let crop=vec2f(min(1.0,outputAspect/sourceAspect),min(1.0,sourceAspect/outputAspect));
  return textureSampleLevel(inputTexture,inputSampler,vec2f(0.5)+(uv-0.5)*crop,0.0);
}

parameters.kernel:
fn resonancePalette(seconds:f32,amount:f32)->vec3f {
  let phase=seconds/12.0;
  let part=u32(floor(phase))%7u;
  let colours=array<vec3f,7>(vec3f(1,0.69,0.39),vec3f(1,0.055,0.1),vec3f(0.95,0.08,0.52),vec3f(0.57,0.16,1),vec3f(0.12,0.32,1),vec3f(0.06,0.82,1),vec3f(0.5,0.12,1));
  return mix(colours[0],mix(colours[part],colours[(part+1u)%7u],smoothstep(0.15,0.85,fract(phase))),clamp(amount,0.0,1.0));
}

fn rotateAxis(p:vec3f,degrees:f32)->vec3f {
  let angle=degrees*0.01745329252;
  let c=cos(angle);let s=sin(angle);
  return vec3f(c*p.x+s*p.z,p.y,-s*p.x+c*p.z);
}


fn fragmentRandom(id:u32,salt:u32)->f32 {
  var state=(id ^ 75u ^ (salt*2891336453u))*747796405u+2891336453u;
  let word=((state >> ((state >> 28u)+4u)) ^ state)*277803737u;
  return f32((word >> 22u) ^ word)*(1.0/4294967296.0);
}

fn rockHash(p:vec3f)->f32 {return fract(sin(dot(p,vec3f(127.1,311.7,74.7)))*43758.5453);}
fn rockNoise(p:vec3f)->f32 {
  let i=floor(p);let f=fract(p);let u=f*f*(3.0-2.0*f);
  return mix(mix(mix(rockHash(i),rockHash(i+vec3f(1,0,0)),u.x),mix(rockHash(i+vec3f(0,1,0)),rockHash(i+vec3f(1,1,0)),u.x),u.y),mix(mix(rockHash(i+vec3f(0,0,1)),rockHash(i+vec3f(1,0,1)),u.x),mix(rockHash(i+vec3f(0,1,1)),rockHash(i+vec3f(1,1,1)),u.x),u.y),u.z);
}

struct Params {
  rotation: f32, // @default 0 Common vertical-axis rotation in degrees.
  paletteCycle: f32, // @default 1 Shared room palette cycle.
  expansion: f32, // @default 0 Bounded radial expansion.
};
fn process(p:Point,ctx:PointCtx)->Point {
  var q=p;
  let row=ctx.index/17u;
  let id=row/9u;
  let latitude=f32(row%9u)/8.0*3.14159265359;
  let longitude=f32(ctx.index%17u)/16.0*6.283185307;
  let unit=vec3f(sin(latitude)*cos(longitude),cos(latitude),sin(latitude)*sin(longitude));
  var radius=10.0;
  for(var face=0u;face<10u;face++) {
    let y=1.0-2.0*(f32(face)+0.5)/10.0;
    let a=f32(face)*2.39996323;
    let normal=vec3f(sqrt(1.0-y*y)*cos(a),y,sqrt(1.0-y*y)*sin(a));
    let projection=dot(unit,normal);
    if(projection>0.0){radius=min(radius,(0.54+fragmentRandom(id,face+81u)*0.25)/projection);}
  }
  let grain=(rockNoise(unit*13.0+f32(id))-0.5)*0.08;
  let local=unit*(min(radius,1.35)+grain)*vec3f(0.65+fragmentRandom(id,43u)*0.35,0.6+fragmentRandom(id,47u)*0.4,0.7+fragmentRandom(id,53u)*0.3);
  let y=fragmentRandom(id,13u)*2.0-1.0;
  let a=fragmentRandom(id,17u)*6.283185307;
  let n=vec3f(sqrt(1.0-y*y)*cos(a),y,sqrt(1.0-y*y)*sin(a));
  let tangent=normalize(cross(n,select(vec3f(0,1,0),vec3f(1,0,0),abs(n.y)>0.9)));
  let bitangent=cross(n,tangent);
  let energy=clamp(ctx.params.expansion,0.0,1.0);
  let turn=f32(id)*2.39996+sin(ctx.absTime*0.12+f32(id))*0.045*energy;
  let x=local.x*cos(turn)-local.y*sin(turn);
  let z=local.x*sin(turn)+local.y*cos(turn);
  // Secondary material is grit only; every large departing piece belongs to the fitted shell.
  let size=0.018+pow(fragmentRandom(id,37u),3.0)*0.065;
  q.size=size*smoothstep(0.12,0.5,energy);
  // Large stones travel less so their entire surface stays inside the same envelope.
  let allowedTravel=min(0.1+3.05*fragmentRandom(id,23u),5.18-size*1.39-2.07);
  q.position=vec3f(0,5.6,0)+rotateAxis(n*(2.07+energy*allowedTravel)+(tangent*x+bitangent*z+n*local.z)*q.size,ctx.params.rotation);
  let mineral=0.4+0.6*rockNoise(unit*33.0+f32(id));
  let brightness=(0.045+fragmentRandom(id,39u)*0.08)*mineral;
  // The centre-facing cut faces catch the warm internal energy.
  let innerGlow=pow(max(0.0,-local.z),2.0)*energy*0.22;
  q.tint=vec4f(vec3f(0.92,0.88,0.81)*brightness+resonancePalette(ctx.absTime,ctx.params.paletteCycle)*innerGlow,1);
  return q;
}

fn resonancePalette(seconds:f32,amount:f32)->vec3f {
  let phase=seconds/12.0;
  let part=u32(floor(phase))%7u;
  let colours=array<vec3f,7>(vec3f(1,0.69,0.39),vec3f(1,0.055,0.1),vec3f(0.95,0.08,0.52),vec3f(0.57,0.16,1),vec3f(0.12,0.32,1),vec3f(0.06,0.82,1),vec3f(0.5,0.12,1));
  return mix(colours[0],mix(colours[part],colours[(part+1u)%7u],smoothstep(0.15,0.85,fract(phase))),clamp(amount,0.0,1.0));
}

fn rotateAxis(p:vec3f,degrees:f32)->vec3f {
  let angle=degrees*0.01745329252;
  let c=cos(angle);let s=sin(angle);
  return vec3f(c*p.x+s*p.z,p.y,-s*p.x+c*p.z);
}


fn fragmentRandom(id:u32,salt:u32)->f32 {
  var state=(id ^ 75u ^ (salt*2891336453u))*747796405u+2891336453u;
  let word=((state >> ((state >> 28u)+4u)) ^ state)*277803737u;
  return f32((word >> 22u) ^ word)*(1.0/4294967296.0);
}

struct Params {
  rotation: f32, // @default 0 Common vertical-axis rotation in degrees.
  expansion: f32, // @default 0 Fragment envelope.
  paletteCycle: f32, // @default 1 Shared room palette cycle.
  highs: f32, // @default 0 Fine-detail energy.
};
fn process(p:Point,ctx:PointCtx)->Point {
  var q=p;
  let id=ctx.index;
  let y=fragmentRandom(id,13u)*2.0-1.0;
  let a=fragmentRandom(id,17u)*6.283185307;
  let n=vec3f(sqrt(1.0-y*y)*cos(a),y,sqrt(1.0-y*y)*sin(a));
  let energy=clamp(ctx.params.expansion,0.0,1.0);
  let radius=2.07+energy*(0.1+2.8*fragmentRandom(id,23u));
  q.position=vec3f(0,5.6,0)+rotateAxis(n*radius,ctx.params.rotation);
  let size=0.012+pow(fragmentRandom(id,37u),4.0)*0.22;
  q.size=size*smoothstep(0.12,0.5,energy);
  let turn=sin(ctx.absTime*0.12+f32(id))*0.045*energy;
  q.orient=normalize(vec4f(n*sin(turn+f32(id)),cos(turn+f32(id))));
  let bright=select(0.085,0.50,fragmentRandom(id,39u)>0.82);
  let sparkle=select(1.0,1.0+ctx.params.highs*8.0,size<0.025);
  q.tint=vec4f(mix(resonancePalette(ctx.absTime,ctx.params.paletteCycle),vec3f(1),0.12)*bright*sparkle,1);
  return q;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  q.position.y = -p.position.y;
  return q;
}

parameters.source:
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  energy: f32, // @default 0 Shell energy.
  beatPulse: f32, // @default 0 Softened tempo pulse, independent of fragment travel.
  bass: f32, // @default 0 Floor pulse energy.
  mids: f32, // @default 0 Wall projection energy.
  highs: f32, // @default 0 Fine light and dust energy.
  transient: f32, // @default 0 Short internal light impulse.
  atmosphere: f32, // @default 0 Slow atmosphere envelope.
  shaftDirection: f32, // @default 1 Light travel: 1 upward, -1 downward, 0 stationary.
  eye: vec3f, // @default 0 2.6 17 Camera position shared with the geometry camera.
  aim: vec3f, // @default 0 4.2 0 Camera target shared with the geometry camera.
  far: f32, // @default 100 Camera far plane for the packed linear view depth.
  fov: f32, // @default 50 Vertical field of view in degrees.
  videoMotion: f32, // @default 0.6 Evolving luminous pattern over video.
  videoGlitch: f32, // @default 0.18 Bounded staggered scanline offsets.
  paletteCycle: f32, // @default 1 Slow amber, orange and violet lighting cycle.
  panelWater: f32, // @default 1 Falling water surface beneath every projection.
  panelVideo: f32, // @default 0 1 projects the connected TimeGrid video cells.
  panelStyle: f32, // @default 0 0 slowly morphs; 1 water, 2 mineral, 3 caustics, 4 constellation.
  coreGradient: f32, // @default 0.65 Colour variation around the warm-white energy centre.
  projectionSeed: f32, // @default 75 Independent, reproducible wall-panel identities.
  panelSequence: f32, // @default 1 1 advances the bar scenes; 0 holds the selected scene.
  panelScene: f32, // @default 1 0 shared, 1 different, 2 alternating, 3 two-thirds, 4 dim, 5 low (dark when held).
  panelClock: f32, // @default 0 1 follows supplied musical bars; 0 uses the independent tempo clock.
  panelPosition: f32, // @default 0 Musical bar plus fractional bar phase, from the audio source.
  beatPosition: f32, // @default 0 Musical beat plus fractional beat phase.
  panelBpm: f32, // @default 112 Sequencer tempo; does not depend on detected audio.
  panelBars: f32, // @default 8 Four-beat bars per scene.
  panelFadeBars: f32, // @default 2 Crossfade length in bars, at the end of each scene.
  panelBrightness: f32, // @default 1 Master projection brightness.
  panelCoverage: f32, // @default 1 Fraction of bays allowed to light; fades by stable rank.
  panelVariety: f32, // @default 1 0 shares content, 1 gives each panel its own content.
  panelAudio: f32, // @default 0.35 Optional mid-band brightness influence; 0 is independent.
  exposure: f32, // @default 1 Scene radiance multiplier.
  haze: f32, // @default 0.045 Scattering density.
  reflection: f32, // @default 0.65 Floor polish.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn panelVideoAt(uv:vec2f)->vec3f {return textureSampleLevel(inputTexture,inputSampler,uv,0.0).rgb;}


fn resonancePalette(seconds:f32,amount:f32)->vec3f {
  let phase=seconds/12.0;
  let part=u32(floor(phase))%7u;
  let colours=array<vec3f,7>(vec3f(1,0.69,0.39),vec3f(1,0.055,0.1),vec3f(0.95,0.08,0.52),vec3f(0.57,0.16,1),vec3f(0.12,0.32,1),vec3f(0.06,0.82,1),vec3f(0.5,0.12,1));
  return mix(colours[0],mix(colours[part],colours[(part+1u)%7u],smoothstep(0.15,0.85,fract(phase))),clamp(amount,0.0,1.0));
}
fn paletteWarm()->vec3f {return resonancePalette(frameU.absTime,params.paletteCycle);}
const CENTRE = vec3f(0,5.6,0);
fn hash(p: vec3f) -> f32 { return fract(sin(dot(p,vec3f(127.1,311.7,74.7)))*43758.5453); }
fn noise(p: vec3f) -> f32 {
  let i=floor(p); let f=fract(p); let u=f*f*(3.0-2.0*f);
  return mix(mix(mix(hash(i),hash(i+vec3f(1,0,0)),u.x),mix(hash(i+vec3f(0,1,0)),hash(i+vec3f(1,1,0)),u.x),u.y),
  mix(mix(hash(i+vec3f(0,0,1)),hash(i+vec3f(1,0,1)),u.x),mix(hash(i+vec3f(0,1,1)),hash(i+vec3f(1,1,1)),u.x),u.y),u.z);
}
fn fbm(p:vec3f)->f32 {return noise(p)*0.55+noise(p*2.03)*0.27+noise(p*4.11)*0.12+noise(p*8.23)*0.06;}
fn energyGradient(p:vec3f)->vec3f {
  let height=smoothstep(-1.3,1.3,p.y-CENTRE.y);
  return mix(paletteWarm()*0.7,mix(paletteWarm(),vec3f(1),0.32),height);
}
fn coreColour(local:vec3f,ray:vec3f)->vec3f {
  let facing=pow(max(0.0,dot(normalize(local),-ray)),5.0);
  let edge=mix(paletteWarm(),energyGradient(local+CENTRE),clamp(params.coreGradient,0.0,1.0));
  let normal=normalize(local);
  let drift=vec3f(frameU.absTime*0.055,-frameU.absTime*0.035,frameU.absTime*0.02);
  let cloud=fbm(normal*5.0+drift);
  let filament=pow(1.0-abs(2.0*noise(normal*11.0+cloud*2.0+drift)-1.0),7.0);
  let secondary=mix(paletteWarm(),vec3f(paletteWarm().b,paletteWarm().r,paletteWarm().g),0.32);
  let textured=mix(edge,secondary,0.18+cloud*0.18)*(0.76+cloud*0.24+filament*0.12);
  return mix(textured,mix(paletteWarm(),vec3f(1),0.86),facing*0.88);
}
fn line(x:f32,width:f32)->f32 {return exp(-abs(x)/width);}
// Analytic room intersections: x is distance, y is surface identity.
fn roomHit(ro:vec3f,rd:vec3f)->vec2f {
  var hit=vec2f(1000,0);
  if(rd.y < -0.00001) {hit=vec2f(-ro.y/rd.y,1);}
  if(rd.y > 0.00001) {
    let t=(13.0-ro.y)/rd.y;
    if(length((ro+rd*t).xz)>=8.45){hit=vec2f(t,2);}
    let roof=(15.0-ro.y)/rd.y;
    if(length((ro+rd*roof).xz)<5.85){hit=vec2f(roof,2);}
    for(var tier=0; tier<4; tier++) {
      let inner=5.85+f32(tier)*0.65;
      let level=14.4-f32(tier)*0.35;
      let distance=(level-ro.y)/rd.y;
      let radius=length((ro+rd*distance).xz);
      if(distance>0.0 && distance<hit.x && radius>=inner && radius<inner+0.65){hit=vec2f(distance,2);}
    }
  }
  let a=dot(rd.xz,rd.xz); let b=dot(ro.xz,rd.xz); let c=dot(ro.xz,ro.xz)-361.0;
  let d=b*b-a*c;
  if(d>0.0 && a>0.00001){let t=(-b+sqrt(d))/a;if(t>0.0 && t<hit.x){hit=vec2f(t,3);}}
  // Low pedestal: the full protected explosion envelope is above this.
  if(rd.y < -0.00001){let t=(0.32-ro.y)/rd.y;let p=ro+rd*t;if(t>0 && t<hit.x && length(p.xz)<2.8){hit=vec2f(t,4);}}
  let bp=dot(ro.xz,rd.xz); let cp=dot(ro.xz,ro.xz)-2.8*2.8;let dp=bp*bp-a*cp;
  if(dp>0 && a>0.00001){let t=(-bp-sqrt(dp))/a;let y=ro.y+rd.y*t;if(t>0 && t<hit.x && y>=0 && y<0.32){hit=vec2f(t,5);}}
  // Peripheral audience terraces leave the central explosion volume unobstructed.
  for(var stepIndex=0;stepIndex<4;stepIndex++){
    let radius=13.0+f32(stepIndex)*1.4;
    let top=0.25*f32(stepIndex+1);
    if(rd.y< -0.00001){let t=(top-ro.y)/rd.y;let q=ro+rd*t;if(t>0 && t<hit.x && length(q.xz)>radius && q.z<2.0){hit=vec2f(t,8);}}
    let disc=b*b-a*(dot(ro.xz,ro.xz)-radius*radius);
    if(disc>0 && a>0.00001){let t=(-b+sqrt(disc))/a;let y=ro.y+rd.y*t;if(t>0 && t<hit.x && y>top-0.25 && y<top && (ro+rd*t).z<2.0){hit=vec2f(t,8);}}
  }
  // Deep oculus reveal, between the main ceiling and its recessed upper aperture.
  let innerD=b*b-a*(dot(ro.xz,ro.xz)-5.85*5.85);
  if(innerD>0.0 && a>0.00001){
    let t=(-b+sqrt(innerD))/a;let y=ro.y+rd.y*t;
    if(t>0.0 && t<hit.x && y>14.4 && y<15.0){hit=vec2f(t,6);}
  }
  // Vertical bronze risers separate the recessed ceiling tiers.
  for(var tier=0; tier<4; tier++) {
    let radius=6.5+f32(tier)*0.65;
    let upper=14.4-f32(tier)*0.35;
    let disc=b*b-a*(dot(ro.xz,ro.xz)-radius*radius);
    if(disc>0.0 && a>0.00001){
      let t=(-b+sqrt(disc))/a;let y=ro.y+rd.y*t;
      if(t>0.0 && t<hit.x && y>upper-0.35 && y<upper){hit=vec2f(t,6);}
    }
  }
  // Structural wall piers project into the room; they are not painted stripes.
  for(var i=0;i<24;i++){
    let angle=f32(i)*0.261799388;
    let centre=vec2f(sin(angle),cos(angle))*18.65;
    let delta=ro.xz-centre;let pb=dot(delta,rd.xz);
    let pd=pb*pb-a*(dot(delta,delta)-0.32*0.32);
    if(pd>0.0 && a>0.00001){let t=(-pb-sqrt(pd))/a;let y=ro.y+t*rd.y;if(t>0.0 && t<hit.x && y>0.0 && y<13.0){hit=vec2f(t,7);}}
  }
  return hit;
}

fn projectionFamily(kind:u32,uv:vec2f,seed:f32,clock:f32)->vec3f {
  if(kind==0u){
    // The moving sheet is shared by every source, including video.
    return mix(vec3f(0.065,0.075,0.085),paletteWarm()*0.10,0.4);
  }
  if(kind==1u){
    let stone=vec3f(uv.x*10.0,uv.y*0.9,seed*31.0+clock*0.07);
    let domain=fbm(stone*0.8);
    let veins=pow(1.0-abs(2.0*fbm(stone*1.7+domain*4.0)-1.0),20.0);
    let strata=0.5+0.5*sin(uv.y*2.1+domain*13.0+clock*0.12);
    return vec3f(0.15,0.18,0.20)*domain*0.08+mix(vec3f(0.40,0.50,0.48),vec3f(0.65,0.38,0.17),strata)*veins*0.5;
  }
  if(kind==2u){
    let sheet=vec2f(uv.x*11.0,uv.y*0.9);
    let bend=sin(sheet.y*1.2+clock*0.35+seed*9.0)*1.3;
    let crossing=sin(sheet.x*1.8+bend+clock*0.2)*sin(sheet.y*1.1-sheet.x*0.7-clock*0.25);
    let caustic=pow(1.0-abs(crossing),18.0);
    let envelope=0.25+0.75*noise(vec3f(sheet*0.6,clock*0.12+seed*31.0));
    return mix(vec3f(0.16,0.36,0.43),vec3f(0.55,0.62,0.65),caustic)*caustic*envelope*0.4;
  }
  let grid=vec2f(uv.x*28.0,uv.y*3.5+clock*0.25);
  let cell=floor(grid);let local=fract(grid);
  let h=hash(vec3f(cell,seed*31.0));
  let centre=vec2f(0.2+0.6*h,0.2+0.6*hash(vec3f(cell,seed*47.0)));
  let d=dot(local-centre,local-centre);
  let star=(exp(-d*150.0)+exp(-d*16.0)*0.06)*smoothstep(0.66,0.9,h);
  let ribbon=pow(0.5+0.5*sin(uv.x*18.0+sin(uv.y*0.7+clock*0.2)*2.5+seed*7.0),16.0)*0.025;
  return vec3f(0.37,0.44,0.64)*(star*0.85+ribbon);
}
fn panelProjection(localUv:vec2f,panelId:f32)->vec3f {
  if(params.panelVideo>0.5){
    // Each architectural bay samples one complete delayed cell, never a strip across cells.
    let cell=u32(panelId)%24u;
    let corner=vec2f(f32(cell%12u),f32(cell/12u));
    let panelUv=vec2f(localUv.x/0.58,1.0-(localUv.y-1.75)/10.45);
    // TimeGrid's 12x2 cells are portrait crops: (512/288)*(2/12).
    // The physical bay is (19*pi/12*0.58) / 10.45 wide/high.
    let crop=vec2f(0.9315,1.0);
    let cadence=frameU.absTime*max(params.panelBpm,1.0)/30.0;
    let stagger=f32(cell%8u)/8.0;
    let tick=cadence-stagger;
    let phase=fract(tick);
    let accent=exp(-phase*9.0);
    let identity=hash(vec3f(f32(cell),params.projectionSeed,61));
    let scan=exp(-pow((panelUv.y-fract(frameU.absTime*0.075+identity))/0.04,2.0));
    let slice=step(0.76,sin(panelUv.y*71.0+floor(tick)*2.3));
    let tear=select(0.0,1.0,(u32(max(floor(tick),0.0))+cell)%7u==0u);
    let shift=vec2f(slice*tear*accent*params.videoGlitch*0.045,0);
    let local=clamp(vec2f(0.5)+(panelUv-0.5)*crop+shift,vec2f(0.025),vec2f(0.975));
    let uv=(corner+local)/vec2f(12,2);
    let centre=dot(panelVideoAt(uv),vec3f(0.2126,0.7152,0.0722));
    let dx=dot(panelVideoAt((corner+clamp(local+vec2f(0.018,0),vec2f(0.025),vec2f(0.975)))/vec2f(12,2)),vec3f(0.2126,0.7152,0.0722))-centre;
    let dy=dot(panelVideoAt((corner+clamp(local+vec2f(0,0.018),vec2f(0.025),vec2f(0.975)))/vec2f(12,2)),vec3f(0.2126,0.7152,0.0722))-centre;
    let luminance=pow(max(centre,0.0),0.55);
    let contour=pow(1.0-abs(fract(luminance*7.0)*2.0-1.0),10.0)*smoothstep(0.035,0.12,luminance);
    let edges=smoothstep(0.008,0.11,length(vec2f(dx,dy)));
    let body=smoothstep(0.07,0.65,luminance)*0.16;
    let ribbons=pow(0.5+0.5*sin(panelUv.x*13.0+sin(panelUv.y*8.0-frameU.absTime*0.4+identity*6.0)*2.0),12.0);
    let overlay=(scan*0.13+ribbons*0.065)*(0.55+accent*0.45)*params.videoMotion;
    let grade=mix(paletteWarm(),vec3f(1),0.06);
    return grade*((body+edges*0.65+contour*0.25)*(0.88+accent*0.18)+overlay);
  }
  let seed=hash(vec3f(panelId,params.projectionSeed,11));
  let identity=hash(vec3f(panelId,params.projectionSeed,37));
  let clock=frameU.absTime*(0.26+seed*0.43);
  let phase=frameU.absTime*0.035+identity*4.0;
  let selected=u32(clamp(floor(params.panelStyle),0.0,4.0));
  let first=select(u32(floor(phase))%4u,selected-1u,selected>0u);
  let next=select((first+1u)%4u,first,selected>0u);
  let blend=select(smoothstep(0.25,0.85,fract(phase)),0.0,selected>0u);
  var projected=projectionFamily(first,localUv,seed,clock);
  if(blend>0.0){projected=mix(projected,projectionFamily(next,localUv,seed,clock),blend);}
  let footlight=0.4+1.0*exp(-max(localUv.y-1.75,0.0)*0.7);
  return mix(projected,projected*paletteWarm()*1.25,params.paletteCycle*0.55)*(0.5+identity)*footlight;
}
// World-space height plus time advects a fixed texture DOWN the wall.
// A seeded sheet keeps moving even when the projected picture is held still.
fn fallingWater(localUv:vec2f,panelId:f32)->vec3f {
  let seed=hash(vec3f(panelId,params.projectionSeed,83));
  let height=localUv.y+frameU.absTime*(1.15+seed*0.4);
  let broad=noise(vec3f(localUv.x*19.0,height*0.7,seed*31.0));
  let flow=noise(vec3f(localUv.x*87.0+broad*2.0,height*1.2,seed*47.0));
  let beads=noise(vec3f(localUv.x*143.0,height*9.0,seed*71.0));
  let threads=pow(1.0-abs(flow*2.0-1.0),10.0);
  let foam=pow(beads,5.0)*(0.25+threads*1.8);
  let sheen=threads*0.42+foam*1.9;
  return vec3f((broad-0.5)*0.012,(flow-0.5)*0.065,sheen);
}
fn panelContent(localUv:vec2f,panelId:f32)->vec3f {
  let amount=clamp(params.panelWater,0.0,1.0);
  if(amount==0.0){return panelProjection(localUv,panelId);}
  let water=fallingWater(localUv,panelId);
  let projected=panelProjection(localUv+water.xy*amount,panelId);
  // Light catches the falling ridges; dark video still leaves the wet surface visible.
  let scattering=mix(paletteWarm(),vec3f(1),0.16)*(0.012+water.z*0.22);
  return projected*mix(1.0,0.55+water.z*1.8,amount)+scattering*amount;
}
fn panelSceneState(panelId:f32,scene:u32)->vec3f {
  // Opacity, independent-content share, brightness. No configuration changes texture time.
  if(scene==0u){return vec3f(1,0,1);}
  if(scene==1u){return vec3f(1,1,1);}
  if(scene==2u){return vec3f(select(0.0,1.0,u32(panelId)%2u==0u),1,1);}
  if(scene==3u){return vec3f(select(0.0,1.0,(u32(panelId)+u32(params.projectionSeed))%3u!=0u),1,1);}
  if(scene==4u){return vec3f(1,0,0.22);}
  return vec3f(1,1,select(0.0,0.18,params.panelSequence>0.5));
}
fn panelLight(localUv:vec2f,panelId:f32)->vec3f {
  let selected=u32(clamp(floor(params.panelScene),0.0,5.0));
  let period=max(params.panelBars,0.25)*4.0*60.0/max(params.panelBpm,1.0);
  let phase=select(frameU.absTime/period,params.panelPosition/max(params.panelBars,0.25),params.panelClock>0.5);
  let automatic=params.panelSequence>0.5;
  let current=(selected+select(0u,u32(floor(phase)),automatic))%6u;
  let following=select(current,(current+1u)%6u,automatic);
  let fadeFraction=clamp(params.panelFadeBars/max(params.panelBars,0.25),0.01,1.0);
  let blend=select(0.0,smoothstep(1.0-fadeFraction,1.0,fract(phase)),automatic);
  let previousState=panelSceneState(panelId,current);
  let to=panelSceneState(panelId,following);
  let variety=clamp(params.panelVariety,0.0,1.0);
  let firstVisible=previousState.x*previousState.z>0.0;
  let secondVisible=to.x*to.z>0.0;
  if(!firstVisible && !secondVisible){return vec3f(0);}
  var sharedContent=vec3f(0);var distinct=vec3f(0);
  if((firstVisible && previousState.y*variety<1.0) || (secondVisible && to.y*variety<1.0)){sharedContent=panelContent(localUv,0.0);}
  if((firstVisible && previousState.y*variety>0.0) || (secondVisible && to.y*variety>0.0)){distinct=panelContent(localUv,panelId+1.0);}
  let first=mix(sharedContent,distinct,previousState.y*variety)*previousState.x*previousState.z;
  let second=mix(sharedContent,distinct,to.y*variety)*to.x*to.z;
  let rank=hash(vec3f(panelId,params.projectionSeed,97))*0.9;
  let coverage=smoothstep(rank,rank+0.1,clamp(params.panelCoverage,0.0,1.0));
  let bank=0.5+0.5*sin(panelId*1.7+params.beatPosition*0.45);
  let hit=params.bass*(0.3+bank*0.55)+params.transient*(0.85-bank*0.5)+params.highs*0.18;
  let brightness=max(params.panelBrightness,0.0)*(0.65+params.panelAudio*(params.mids*0.65+hit*1.7));
  return mix(first,second,blend)*coverage*brightness;
}

// A shallow veil hugs the oculus; its support never reaches the sphere or outer hall.
fn ceilingVeil(p:vec3f)->f32 {
  let radius=length(p.xz);
  if(p.y<10.8 || p.y>15.0 || radius>8.5){return 0.0;}
  let angle=frameU.absTime*0.055;
  let q=vec2f(cos(angle)*p.x-sin(angle)*p.z,sin(angle)*p.x+cos(angle)*p.z);
  let inward=radius+frameU.absTime*0.16;
  let curls=fbm(vec3f(q*0.65,p.y*1.2)+vec3f(0,inward*0.35,frameU.absTime*0.035));
  let height=exp(-pow((p.y-(13.35+curls*0.45))/0.65,2.0));
  let annulus=exp(-pow((radius-5.6)/2.1,2.0))*(1.0-smoothstep(7.6,8.5,radius));
  return height*annulus*smoothstep(0.22,0.78,curls)*(0.25+clamp(params.atmosphere,0.0,1.0)*0.75);
}

// Blend two continuous travel clocks: changing energy never multiplies elapsed time.
fn shaftOpening()->f32 {return smoothstep(0.0,0.15,clamp(params.energy,0.0,1.0));}
fn shaftDrive()->f32 {return smoothstep(0.15,0.85,clamp(params.energy,0.0,1.0));}
fn shaftWave(height:f32,identity:f32,rate:f32)->f32 {
  let phase=-params.shaftDirection*params.beatPosition*rate+height*0.05+0.18-identity*0.07;
  // GPU cosine may undershoot -1 slightly; pow requires a nonnegative base.
  return pow(clamp(0.5+0.5*cos(phase*6.2831853),0.0,1.0),36.0);
}
fn shaftPacket(height:f32,identity:f32)->f32 {
  return mix(shaftWave(height,identity,0.025),shaftWave(height,identity,0.07),shaftDrive());
}
// One faint candidate at low energy; up to four independently staggered accents at peaks.
fn shaftAccent(strand:u32)->f32 {
  if(strand%14u!=0u){return 0.0;}
  let rank=f32(strand/14u)*0.25;
  return shaftOpening()*(1.0-smoothstep(shaftDrive()+0.04,shaftDrive()+0.16,rank));
}
fn shaftPulseGain()->f32 {
  return shaftOpening()*(0.045+shaftDrive()*(0.65+clamp(params.bass,0.0,1.0)*0.12
    +clamp(params.transient,0.0,1.0)*0.15+clamp(params.beatPulse,0.0,1.0)*0.08));
}
// A closed shell keeps a dim architectural filament; percussion cannot expose its light.
fn shaftBaseGain()->f32 {
  let opening=clamp(params.energy,0.0,1.0);
  return 0.012+opening*opening*(1.1+clamp(params.highs,0.0,1.0)*0.25+clamp(params.beatPulse,0.0,1.0)*0.25);
}
fn shaftVolumeGain()->f32 {
  let opening=clamp(params.energy,0.0,1.0);
  return 0.0012+opening*opening*0.22*(0.6+clamp(params.highs,0.0,1.0));
}
// Keep the accent close to the filament instead of creating a broad white bead.
fn shaftBulbWidth(baseWidth:f32,packet:f32)->f32 {
  return baseWidth*(1.0+1.25*packet*shaftOpening()*(0.3+0.7*shaftDrive()));
}
fn shaftAccentColour()->vec3f {
  return mix(paletteWarm(),sqrt(paletteWarm()),0.25);
}

// Shared smooth envelope: no strand ends halfway through the foreground volume.
fn shaftEnvelope(height:f32,landing:f32)->f32 {
  return smoothstep(landing,landing+2.2,height)*(1.0-smoothstep(12.8,15.0,height))*mix(0.3,1.0,smoothstep(2.0,8.0,height));
}
// Approximate the Gaussian integral up to the visible surface, rather than clipping
// an entire strand when its closest point crosses that surface.
fn shaftVisibility(beforeSurface:f32,width:f32)->f32 {
  return smoothstep(-1.5,1.5,beforeSurface/width);
}

fn surface(p:vec3f,rd:vec3f,id:f32)->vec3f {
  let r=length(p.xz);
  let rock=fbm(p*2.3);
  let fine=noise(p*51.0);
  let warm=paletteWarm();
  var col=vec3f(0.014,0.013,0.012)*(0.6+rock);
  if(id==8.0){
    col=vec3f(0.007,0.008,0.01)*(0.6+rock);
    let seam=abs(fract((r-13.0)/1.4+0.5)-0.5);
    col+=paletteWarm()*line(seam,0.007)*line(fract(p.y*4.0),0.04)*0.08;
    let angle=atan2(p.x,p.z);
    let fixture=pow(max(0.0,cos(angle*24.0)),110.0);
    col+=paletteWarm()*fixture*line(p.y-0.75,0.05)*0.8;
  } else if(id==6.0){
    col=vec3f(0.032,0.021,0.012)*(0.4+rock);
    col+=paletteWarm()*(line(p.y-13.1,0.018)+line(p.y-14.4,0.022))*2.2;
    col*=0.5+0.5*smoothstep(0.01,0.05,abs(sin(atan2(p.x,p.z)*28.0)));
  } else if(id==7.0){
    col=vec3f(0.006,0.006,0.007)*(0.5+rock);
    col+=paletteWarm()*0.025*exp(-(13.0-p.y)*0.5)*(0.2+fine);
    col+=paletteWarm()*0.018*exp(-p.y*1.2);
  } else if(id==3.0){
    let angle=atan2(p.x,p.z);
    let bay=angle*12.0/3.14159265;
    let fraction=fract(bay);
    let seam=min(fraction,1.0-fraction);
    let pillar=1.0-smoothstep(0.04,0.14,seam);
    let mineral=fbm(p*vec3f(7.0,0.65,7.0));
    let strata=pow(1.0-abs(2.0*noise(p*vec3f(18.0,1.2,18.0)+mineral*3.0)-1.0),10.0);
    let illumination=0.12+0.9*exp(-(13.0-p.y)*0.7)+0.5*exp(-p.y*1.3);
    col=vec3f(0.018,0.016,0.014)*(0.3+rock*0.8)*(1.0-0.7*pillar)*illumination;
    let toplight=line(p.y-12.45,0.05)*smoothstep(0.04,0.15,seam);
    let fixture=hash(vec3f(floor(bay),2,7));
    let stripHeight=smoothstep(0.6+fixture*2.0,1.3+fixture*2.0,p.y)*(1.0-smoothstep(5.0+fixture*5.0,6.0+fixture*5.0,p.y));
    let strip=line(fraction-0.12,0.0018)*stripHeight;
    // A slow architectural chase is separate from the percussion accents.
    let lightPhrase=frameU.absTime*max(params.panelBpm,1.0)/60.0*0.19634954;
    let sweep=pow(0.5+0.5*sin(lightPhrase-floor(bay)*0.7),3.0);
    let stripGain=0.22+sweep*1.5+params.transient*(0.3+fixture*0.7);
    let bank=0.5+0.5*sin(floor(bay)*1.7+params.beatPosition*0.45);
    let accent=params.transient*(0.3+bank*0.7)+params.bass*(0.7-bank*0.35);
    let coveGain=0.65+params.atmosphere*0.6+sweep*0.55+accent*1.5;
    col+=warm*(toplight*coveGain+strip*stripGain);
    // The moving fixtures illuminate the adjacent stone, including its reflection environment.
    let stripWash=exp(-abs(fraction-0.12)*32.0)*stripHeight;
    col+=warm*stripWash*stripGain*0.055*(0.25+mineral+strata);
    col+=warm*0.065*coveGain*exp(-(13.0-p.y)*0.6)*(0.1+mineral*0.7+strata*1.2);
    col+=vec3f(0.014,0.016,0.018)*strata*illumination;
    col+=warm*0.16*exp(-p.y*0.65)*pow(max(0.0,cos(fraction*6.2831853)),6.0);
    let panelId=floor(bay)+12.0;
    let panel=smoothstep(0.25,0.27,fraction)*(1.0-smoothstep(0.81,0.83,fraction))*smoothstep(1.75,1.95,p.y)*(1.0-smoothstep(12.0,12.2,p.y));
    if(panel>0.0){col+=panel*panelLight(vec2f(fraction-0.25,p.y),panelId);}
    col*=0.8+0.3*fine;
    let footing=1.0-smoothstep(0.65,0.85,p.y);
    col=mix(col,vec3f(0.008,0.007,0.006)*(0.5+rock),footing);
    col+=paletteWarm()*line(p.y-0.22,0.025)*0.6;

  } else if(id==2.0){
    col=vec3f(0.012,0.008,0.005)*(0.55+rock);
    let aperture=smoothstep(5.7,5.85,r);
    col*=aperture;
    let rings=line(r-5.85,0.024)+line(r-6.40,0.014)+line(r-7.05,0.014)+line(r-7.70,0.014)+line(r-8.35,0.018);
    col+=warm*rings*(1.2+params.atmosphere*0.8+params.highs*0.25+params.beatPulse*0.2);
    col+=warm*0.12*line(r-6.0,0.55);
    let azimuth=atan2(p.x,p.z);
    let inlay=line(r-6.68,0.012)+line(r-7.39,0.008)+line(r-8.05,0.012);
    let facets=pow(0.5+0.5*cos(azimuth*48.0),12.0);
    let travellingLight=pow(0.5+0.5*cos(azimuth*3.0+frameU.absTime*0.12),6.0);
    col+=warm*inlay*facets*(0.08+travellingLight*0.6)*(0.35+params.atmosphere);
    let radial=abs(sin(atan2(p.x,p.z)*32.0));
    col*=0.3+0.7*smoothstep(0.01,0.08,radial);
  } else if(id==1.0){
    let course=floor(p.z/1.4);
    let joints=abs(fract(vec2f((p.x+select(0.0,0.55,i32(course)%2==0))/1.1,p.z/1.4)+0.5)-0.5);
    let slab=min(joints.x,joints.y);
    let slabId=vec3f(floor((p.x+select(0.0,0.55,i32(course)%2==0))/1.1),course,17);
    let stoneVeins=pow(1.0-abs(2.0*fbm(p*2.7+rock*4.0)-1.0),12.0);
    col=vec3f(0.014,0.012,0.010)*(0.35+rock+stoneVeins*0.7)*(0.6+hash(slabId)*0.8)*smoothstep(0.002,0.012,slab);
    let rings=line(r-3.4,0.018)+line(r-3.8,0.025)+line(r-4.8,0.018)+line(r-4.95,0.012);
    let wave=pow(max(0.0,sin(r*3.4-params.beatPosition*6.2831853)),18.0)*exp(-max(r-3.0,0.0)*0.5);
    let strike=pow(clamp(params.bass,0.0,1.0),1.5);
    col+=warm*rings*(0.35+strike*11.0);
    // Light washes the neighbouring wet stone rather than living only on a subpixel tube.
    let ringSpill=line(r-3.4,0.14)+line(r-3.8,0.17)+line(r-4.8,0.14)+line(r-4.95,0.10);
    let stoneResponse=(0.35+rock*0.65)*smoothstep(0.002,0.012,slab);
    col+=warm*ringSpill*(0.012+strike*0.85)*stoneResponse;
    let ringFront=3.0+fract(params.beatPosition)*4.5;
    let travelling=exp(-pow((r-ringFront)/0.15,2.0))*smoothstep(2.8,3.2,r)*(1.0-smoothstep(6.2,7.5,r));
    col+=warm*(wave*0.35+travelling*1.4)*strike;
  } else {
    col=vec3f(0.024,0.017,0.01)*(0.5+rock)+warm*0.012;
    if(id==4.0){
      col+=warm*line(r-2.74,0.014)*1.3;
      let arrival=(0.025+params.energy*0.22+params.beatPulse*0.08)*exp(-r*r*0.85);
      let engraving=line(r-1.95,0.009)+line(r-2.12,0.006)+line(r-2.43,0.009);
      let sweep=pow(0.5+0.5*cos(atan2(p.x,p.z)*3.0-frameU.absTime*0.18),8.0);
      col+=warm*(arrival*(0.65+fine*0.35)+engraving*(0.035+sweep*0.18)*(0.3+params.atmosphere));
    }
    if(id==5.0){col+=warm*line(p.y-0.28,0.014)*2.0;col*=0.55+fine*0.45;}
  }
  let spill=2.0/(1.0+dot(p-CENTRE,p-CENTRE));
  col+=warm*spill*(0.1+params.energy*0.25)*rock;
  return col;
}

@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
  let azimuth=(uv.x-0.5)*6.283185307;
  let elevation=uv.y*3.14159265;
  let rd=vec3f(sin(elevation)*sin(azimuth),cos(elevation),-sin(elevation)*cos(azimuth));
  let hit=roomHit(CENTRE,rd);
  return vec4f(surface(CENTRE+rd*hit.x,rd,hit.y)*params.exposure,1);
}

struct Params {
  amount: f32, // @default 1  0 is the input exactly, 1 is full FXAA.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> params: Params;

const SPAN_MAX: f32 = 8.0;
const REDUCE_MUL: f32 = 0.125;
const REDUCE_MIN: f32 = 0.0078125;

fn tap(uv: vec2f) -> vec3f {
  return textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
}

fn luma(c: vec3f) -> f32 {
  let t = max(c, vec3f(0.0)) / (vec3f(1.0) + max(c, vec3f(0.0)));
  return dot(t, vec3f(0.299, 0.587, 0.114));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputTexture));
  let centre = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let m = centre.rgb;
  let lM = luma(m);
  let lNW = luma(tap(uv + vec2f(-1.0, -1.0) * px));
  let lNE = luma(tap(uv + vec2f(1.0, -1.0) * px));
  let lSW = luma(tap(uv + vec2f(-1.0, 1.0) * px));
  let lSE = luma(tap(uv + vec2f(1.0, 1.0) * px));
  let lMin = min(lM, min(min(lNW, lNE), min(lSW, lSE)));
  let lMax = max(lM, max(max(lNW, lNE), max(lSW, lSE)));

  var dir = vec2f(-((lNW + lNE) - (lSW + lSE)), (lNW + lSW) - (lNE + lSE));
  let reduce = max((lNW + lNE + lSW + lSE) * 0.25 * REDUCE_MUL, REDUCE_MIN);
  let rcpMin = 1.0 / (min(abs(dir.x), abs(dir.y)) + reduce);
  dir = clamp(dir * rcpMin, vec2f(-SPAN_MAX), vec2f(SPAN_MAX)) * px;

  let a = 0.5 * (tap(uv + dir * (1.0 / 3.0 - 0.5)) + tap(uv + dir * (2.0 / 3.0 - 0.5)));
  let b = a * 0.5 + 0.25 * (tap(uv - dir * 0.5) + tap(uv + dir * 0.5));
  let lB = luma(b);
  let smoothed = select(b, a, (lB < lMin) || (lB > lMax));
  // Alpha passes through untouched: an edge-smoothing pass has no business deciding coverage
  // (T1276 found the first version writing 1 over a plate that carried 0).
  return vec4f(mix(m, smoothed, params.amount), centre.a);
}

parameters.kernel:
fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  q.position.y = -p.position.y;
  return q;
}

fn process(p:Point,ctx:PointCtx)->Point {
  var q=p; q.position.y=-p.position.y; q.end.y=-p.end.y; return q;
}

fn resonancePalette(seconds:f32,amount:f32)->vec3f {
  let phase=seconds/12.0;
  let part=u32(floor(phase))%7u;
  let colours=array<vec3f,7>(vec3f(1,0.69,0.39),vec3f(1,0.055,0.1),vec3f(0.95,0.08,0.52),vec3f(0.57,0.16,1),vec3f(0.12,0.32,1),vec3f(0.06,0.82,1),vec3f(0.5,0.12,1));
  return mix(colours[0],mix(colours[part],colours[(part+1u)%7u],smoothstep(0.15,0.85,fract(phase))),clamp(amount,0.0,1.0));
}

fn rotateAxis(p:vec3f,degrees:f32)->vec3f {
  let angle=degrees*0.01745329252;
  let c=cos(angle);let s=sin(angle);
  return vec3f(c*p.x+s*p.z,p.y,-s*p.x+c*p.z);
}

fn rockHash(p:vec3f)->f32 {return fract(sin(dot(p,vec3f(127.1,311.7,74.7)))*43758.5453);}
fn rockNoise(p:vec3f)->f32 {
  let i=floor(p);let f=fract(p);let u=f*f*(3.0-2.0*f);
  return mix(mix(mix(rockHash(i),rockHash(i+vec3f(1,0,0)),u.x),mix(rockHash(i+vec3f(0,1,0)),rockHash(i+vec3f(1,1,0)),u.x),u.y),mix(mix(rockHash(i+vec3f(0,0,1)),rockHash(i+vec3f(1,0,1)),u.x),mix(rockHash(i+vec3f(0,1,1)),rockHash(i+vec3f(1,1,1)),u.x),u.y),u.z);
}

struct Params {
  rotation: f32, // @default 0 Common vertical-axis rotation in degrees.
  paletteCycle: f32, // @default 1 Shared room palette cycle.
  gain: f32, // @default 0 Energy visible at the exposed cut lip.
